<script setup lang="ts">
import {ref,computed,onBeforeUnmount} from 'vue';
import {request,ApiError,type Guest} from '../lib/api';
import {mbtiGroups,avatarThumbnail,uploadProfileAvatar} from '../lib/profile';
const props=defineProps<{me:Guest}>();const emit=defineEmits<{(e:'updated',me:Guest):void;(e:'auth-expired'):void}>();
const nickname=ref(props.me.nickname||props.me.username),mbti=ref(props.me.mbti||''),busy=ref(false),error=ref(''),success=ref(''),preview=ref(''),blob=ref<Blob|null>(null),preparing=ref(false),fileInput=ref<HTMLInputElement|null>(null);
let disposed=false,sequence=0;const profileInitial=computed(()=>Array.from(nickname.value.trim()||props.me.username)[0]||'鱼');const shownAvatar=computed(()=>preview.value||props.me.avatar_url||'');
function fail(e:unknown){if(disposed)return;if(e instanceof ApiError&&e.status===401)emit('auth-expired');if(!(e instanceof ApiError&&e.status===0))error.value=(e as Error).message;}
async function pick(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||busy.value)return;const n=++sequence;preparing.value=true;error.value='';success.value='';try{const b=await avatarThumbnail(file);if(disposed||n!==sequence)return;if(preview.value)URL.revokeObjectURL(preview.value);blob.value=b;preview.value=URL.createObjectURL(b);}catch(e){fail(e);}finally{if(!disposed&&n===sequence)preparing.value=false;}}
function discard(){sequence++;preparing.value=false;if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';blob.value=null;}
async function saveAvatar(){if(!blob.value||busy.value)return;busy.value=true;error.value='';try{const me=await uploadProfileAvatar(blob.value);if(disposed)return;emit('updated',me);discard();success.value='头像已换好，去鱼塘露个脸。';}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
async function clearAvatar(){if(busy.value)return;busy.value=true;error.value='';try{const me=await request<Guest>('/profile/avatar/delete','POST',{});if(disposed)return;emit('updated',me);discard();success.value='已恢复文字头像。';}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
async function save(){if(busy.value)return;error.value='';success.value='';if(!nickname.value.trim()||[...nickname.value.trim()].length>24){error.value='昵称填写1–24字。';return;}busy.value=true;try{const me=await request<Guest>('/profile','POST',{nickname:nickname.value.trim(),mbti:mbti.value});if(disposed)return;emit('updated',me);nickname.value=me.nickname||me.username;success.value='资料已更新，大厅名片也一起换好了。';}catch(e){fail(e);}finally{if(!disposed)busy.value=false;}}
onBeforeUnmount(()=>{disposed=true;discard();});
</script>
<template><view class="personal-center"><text class="eyebrow">PROFILE / 你的摸鱼工牌</text><text class="title">个人中心</text><text class="subtitle">工号是工号，名字可以由自己决定。</text>
<view class="profile-grid"><view class="profile-card identity"><view class="portrait"><component :is="'img'" v-if="shownAvatar" :src="shownAvatar" alt="头像预览"/><text v-else>{{profileInitial}}</text></view><text class="display-name">{{nickname.trim()||me.username}}</text><text class="account">@{{me.username}}</text><text v-if="mbti" class="mbti-badge">{{mbti}}</text><text class="preview-label">大厅名片预览</text>
<component :is="'input'" ref="fileInput" type="file" accept="image/jpeg,image/png,image/webp" class="file-input" @change="pick"/><button :disabled="busy||preparing" @click="fileInput?.click()">{{preparing?'正在整理头像…':'选一张新头像'}}</button><view v-if="blob" class="avatar-actions"><button class="save-avatar" :disabled="busy" @click="saveAvatar">保存头像</button><button :disabled="busy" @click="discard">取消</button></view><button v-else-if="me.avatar_url" class="text-button" :disabled="busy" @click="clearAvatar">恢复文字头像</button><text class="hint">图片居中裁成正方形，先预览再保存。支持 JPG / PNG / WebP，原图最多10MB，保存为256像素小头像。</text></view>
<view class="profile-card"><text class="section">对外营业资料</text><text class="label">大厅昵称</text><input v-model="nickname" :maxlength="24" placeholder="例如：带薪发呆研究员" class="nickname-input"/><text class="hint">昵称可以重名，聊天中会附带固定的 @账号，避免认错人。</text><view class="mbti-heading"><text class="label">我的 MBTI</text><button :class="{selected:!mbti}" :disabled="busy" @click="mbti=''">暂不设置</button></view><view v-for="group in mbtiGroups" :key="group.name" class="mbti-group"><text>{{group.name}}</text><view><button v-for="type in group.types" :key="type" :class="{selected:mbti===type}" :aria-pressed="mbti===type" :disabled="busy" @click="mbti=type">{{type}}</button></view></view><text class="hint">只是一张性格标签，不是性格判决书。这里设置的是你自己，不会更改“精神疗愈”的 AI 角色。</text><button class="save-profile" :disabled="busy||preparing" @click="save">{{busy?'正在保存…':'保存我的工牌'}}</button><text class="hint">昵称、头像和 MBTI 会展示在公共大厅。登录账号与密码不受影响。</text></view></view><text v-if="error" class="profile-error" role="alert">{{error}}</text><text v-if="success" class="profile-success" role="status">{{success}}</text></view></template>
<style scoped>
.personal-center{max-width:1000px;margin:auto;color:#778164;padding:25px 0}.eyebrow{font-size:10px;color:#a2ad91;letter-spacing:2px;display:block}.title{font-size:32px;font-weight:700;display:block;margin:12px 0}.subtitle{font-size:13px;color:#9aa28b}.profile-grid{display:grid;grid-template-columns:290px minmax(0,1fr);gap:22px;margin-top:28px}.profile-card{background:#fffef8;border:1px solid #e3e7d7;border-radius:22px;padding:26px;min-width:0}.identity{display:flex;flex-direction:column;align-items:center;gap:12px;height:fit-content;text-align:center}.portrait{width:104px;height:104px;border-radius:32px;background:linear-gradient(135deg,#dce7c8,#eee6ed);overflow:hidden;display:flex;justify-content:center;align-items:center;font-size:38px;color:#8a9774;margin:8px}.portrait img{width:100%;height:100%;object-fit:cover}.display-name{font-size:20px;font-weight:600;overflow-wrap:anywhere;max-width:100%}.account{font-size:12px;color:#b0b59f;overflow-wrap:anywhere}.mbti-badge{background:#eee8f4;padding:4px 13px;border-radius:20px;font-size:11px;color:#a08cb0}.preview-label{font-size:10px;color:#b5b9a7}.personal-center button{margin:0;font-size:12px;line-height:1.6;padding:10px 14px;border:1px solid transparent;border-radius:10px;background:#edf1e1;color:#83936b}.personal-center button::after{border:0}.file-input{display:none}.avatar-actions{display:flex;gap:8px}.personal-center .save-avatar,.personal-center .save-profile{background:#899b70;color:#fffdf6}.personal-center .text-button{background:transparent;color:#a9a38c;font-size:11px}.hint{display:block;font-size:11px;line-height:1.9;color:#a5ab97;margin-top:10px}.section{display:block;font-size:19px;font-weight:600;margin-bottom:20px}.label{display:block;font-size:12px;margin:14px 0 9px}.nickname-input{background:#f8f9f0;border:1px solid #e0e5d1;border-radius:12px;padding:13px;color:#778660;font-size:14px;height:22px}.mbti-heading{display:flex;align-items:center;justify-content:space-between;margin:22px 0 10px}.mbti-heading button{font-size:10px;padding:5px 9px}.mbti-group{margin-bottom:15px}.mbti-group>text{font-size:10px;color:#a9ad9a;display:block;margin-bottom:7px}.mbti-group>view{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.mbti-group button{background:#f4f3ec;font-size:12px;padding:9px 5px}.personal-center button.selected{border-color:#b5c49a;background:#e5edd5;color:#748958}.personal-center .save-profile{width:100%;margin-top:22px}.profile-error,.profile-success{display:block;margin-top:20px;padding:14px 18px;border-radius:12px;font-size:13px;background:#f6e9df;color:#ae826a}.profile-success{background:#ecf1e0;color:#7e9360}button:focus-visible{outline:2px solid #9eaf85;outline-offset:2px}@media(max-width:760px){.profile-grid{grid-template-columns:1fr}.profile-card{padding:22px}.identity{height:auto}.title{font-size:28px}.portrait{width:90px;height:90px}.identity .hint{max-width:290px}}
</style>
